# Let's check available packages
import sys
print(sys.version)

try:
    import pysat
    print("PySAT available:", pysat.__version__)
except ImportError as e:
    print("PySAT not available:", e)

try:
    import z3
    print("Z3 available:", z3.get_version_string())
except ImportError as e:
    print("Z3 not available:", e)

try:
    import pycosat
    print("pycosat available")
except ImportError as e:
    print("pycosat not available:", e)

import z3

n = 17
min_edges = 30

s = z3.Solver()

# Edge variables
edge = {}
for i in range(n):
    for j in range(i+1, n):
        edge[(i,j)] = z3.Bool(f"e_{i}_{j}")

# Path of length 2 variables: path2[i][j] = there exists k such that edge(i,k) and edge(k,j)
path2 = {}
for i in range(n):
    for j in range(n):
        if i != j:
            path2[(i,j)] = z3.Bool(f"p2_{i}_{j}")

# Path of length 3 variables
path3 = {}
for i in range(n):
    for j in range(n):
        if i != j:
            path3[(i,j)] = z3.Bool(f"p3_{i}_{j}")

# Define path2: path2[i][j] <-> exists k != i,j: edge(i,k) AND edge(k,j)
for i in range(n):
    for j in range(n):
        if i != j:
            # path2[i][j] is true iff there is some k connecting i and j
            disjuncts = []
            for k in range(n):
                if k != i and k != j:
                    e_ik = edge[(min(i,k), max(i,k))]
                    e_kj = edge[(min(k,j), max(k,j))]
                    disjuncts.append(z3.And(e_ik, e_kj))
            s.add(path2[(i,j)] == z3.Or(disjuncts))

# Define path3: path3[i][j] <-> exists k != i,j: edge(i,k) AND path2(k,j)
for i in range(n):
    for j in range(n):
        if i != j:
            disjuncts = []
            for k in range(n):
                if k != i and k != j:
                    e_ik = edge[(min(i,k), max(i,k))]
                    disjuncts.append(z3.And(e_ik, path2[(k,j)]))
            s.add(path3[(i,j)] == z3.Or(disjuncts))

# Girth constraint: for all i != j, at most one of edge, path2, path3 is true
for i in range(n):
    for j in range(i+1, n):
        # edge[i][j] is the direct edge
        # path2[i][j] and path2[j][i] are symmetric but we defined both
        # Actually path2 is directed, but edge is undirected.
        # If there's an edge (i,j), then edge[i][j] is true.
        # We need: NOT (edge[i][j] AND path2[i][j])
        # And: NOT (edge[i][j] AND path3[i][j])
        # And: NOT (path2[i][j] AND path3[i][j])
        # Also need to consider path2[j][i] and path3[j][i]?
        # path2[i][j] means there's a path i-k-j. This is symmetric: if i-k-j then also j-k-i.
        # So path2[i][j] == path2[j][i]. Similarly for path3.
        # But we defined both directions. Let's just use one direction.

        e = edge[(i,j)]
        p2 = path2[(i,j)]
        p3 = path3[(i,j)]

        # At most one true
        s.add(z3.Not(z3.And(e, p2)))
        s.add(z3.Not(z3.And(e, p3)))
        s.add(z3.Not(z3.And(p2, p3)))

# Edge count >= 30
edge_vars = [edge[k] for k in edge]
s.add(z3.PbGe([(v, 1) for v in edge_vars], min_edges))

# 4-colorability
colors = [z3.Int(f"c_{i}") for i in range(n)]
for i in range(n):
    s.add(colors[i] >= 0, colors[i] <= 3)
for (i,j), e in edge.items():
    s.add(z3.Implies(e, colors[i] != colors[j]))

print("Solving...")
result = s.check()
print("Result:", result)

if result == z3.sat:
    model = s.model()
    edge_list = []
    for (i,j), e in edge.items():
        if z3.is_true(model.evaluate(e)):
            edge_list.append((i,j))
    print(f"Found graph with {len(edge_list)} edges")
    print("Edges:", edge_list)

    # Verify
    adj = {i: set() for i in range(n)}
    for u,v in edge_list:
        adj[u].add(v)
        adj[v].add(u)

    # BFS shortest cycle
    from collections import deque
    def find_shortest_cycle():
        best = float('inf')
        for start in range(n):
            parent = [-1]*n
            dist = [-1]*n
            queue = deque([start])
            dist[start] = 0
            while queue:
                u = queue.popleft()
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u] + 1
                        parent[v] = u
                        queue.append(v)
                    elif v != parent[u]:
                        cycle_len = dist[u] + dist[v] + 1
                        if cycle_len < best:
                            best = cycle_len
        return best

    g = find_shortest_cycle()
    print(f"Girth: {g}")

    coloring = [model.evaluate(colors[i]).as_long() for i in range(n)]
    print("Coloring:", coloring)
    ok = True
    for u,v in edge_list:
        if coloring[u] == coloring[v]:
            print(f"ERROR: edge ({u},{v}) has same color")
            ok = False
    print("Coloring valid:", ok)
else:
    print("UNSAT")
